#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_list_lines(chip, &line, NULL) < 0) {
        perror("gpiod_chip_list_lines");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (line->number != 2 || line->direction != GPIOD_DIR_OUT) {
        fprintf(stderr, "GPIO 2 is not an output\n");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_fd(chip, line->number, &fd) < 0) {
        perror("gpiod_chip_get_fd");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_line_request_fd(line, &fd) < 0) {
        perror("gpiod_line_request_fd");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_line_request_loop(line, &loop) < 0) {
        perror("gpiod_line_request_loop");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        gpiod_loop_poll(loop, 2);
        if (gpiod_loop_has_error(loop)) {
            fprintf(stderr, "Error: %s\n", gpiod_loop_strerror(loop));
            break;
        }
        printf("Output set to 1\n");
        gpiod_line_set_value(line, 1);
        sleep(2);
        printf("Output set to 0\n");
        gpiod_line_set_value(line, 0);
    }

    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
