int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int state = 0;
    int err;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 2)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_unlink(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if ((err = gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT)) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_chip_unlink(chip);
        gpiod_line_unlink(line);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high (1)
    if ((err = gpiod_line_set_value(line, 1)) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_unlink(chip);
        gpiod_line_unlink(line);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge for reading
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_chip_unlink(chip);
        gpiod_line_unlink(line);
        gpiod_close(fd);
        return 1;
    }

    // Loop indefinitely, applying state changes every 5 seconds
    while (1) {
        // Print the current state
        printf("State: %d\n", state);

        // Apply state change
        if (state == 0) {
            if ((err = gpiod_line_set_value(line, 0)) < 0) {
                perror("gpiod_line_set_value");
                gpiod_chip_unlink(chip);
                gpiod_line_unlink(line);
                gpiod_line_unlink(edge);
                gpiod_close(fd);
                return 1;
            }
            state = 1;
        } else {
            if ((err = gpiod_line_set_value(line, 1)) < 0) {
                perror("gpiod_line_set_value");
                gpiod_chip_unlink(chip);
                gpiod_line_unlink(line);
                gpiod_line_unlink(edge);
                gpiod_close(fd);
                return 1;
            }
            state = 0;
        }

        // Sleep for 5 seconds
        if (sleep(5) == -1) {
            perror("sleep");
            gpiod_chip_unlink(chip);
            gpiod_line_unlink(line);
            gpiod_line_unlink(edge);
            gpiod_close(fd);
            return 1;
        }
    }

    // Cleanup on exit
    gpiod_chip_unlink(chip);
    gpiod_line_unlink(line);
    gpiod_line_unlink(edge);
    gpiod_close(fd);

    return 0;
}

