        perror("Failed to set slave address");
        goto cleanup;
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 2;
    msg[0].data[0] = ADC_CHANNEL;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 2;
    msg[1].data[0] = 0x00;
    msg[1].data[1] = 0x00;

    while (1) {
        if (ioctl(fd, I2C_RDWR, msg, &rdwr_msg) < 0) {
            perror("Failed to read ADC");
            goto cleanup;
        }

        buf[0] = rdwr_msg.data[0];
        buf[1] = rdwr_msg.data[1];

        printf("%f\n", (float)buf[0] / 0x80.0);

        usleep(500000); // 0.5 seconds
    }

cleanup:
