void i2c_read_temp() {
    if (i2c_fd == -1) {
        perror("i2c_fd is not open");
        return;
    }

    struct i2c_msg msg[1];
    struct i2c_rdma_request req;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 1;
    msg[0].data[0] = MLX90614_REG_TEMP;

    req.request = msg[0].addr;
    req.offset = 0;
    req.len = 1;
