        perror("gpiod_line_request_output");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to ECHO state
    if (gpiod_line_set_value(line, ECHO) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
