int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int state;
    int distance;
    int count = 0;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the chip
    if ((chip = gpiod_chip_from_fd(fd)) == NULL) {
        perror("gpiod_chip_from_fd");
        gpiod_close(fd);
        return 1;
    }

    // Get the line
    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        fprintf(stderr, "GPIO %d not found\n", GPIO17);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Start the edge
    if (gpiod_edge_start(edge) < 0) {
        perror("gpiod_edge_start");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        // Wait for an edge
        if (gpiod_edge_wait(edge, &state) < 0) {
            fprintf(stderr, "Error waiting for edge\n");
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        // Calculate distance
        if (state == 1) {
            // Trigger the HC-SR04
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                gpiod_line_free(line);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }

            // Wait for the echo
            if (gpiod_edge_wait(edge, &state) < 0) {
                fprintf(stderr, "Error waiting for echo\n");
                gpiod_line_free(line);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }

            // Stop the HC-SR04
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                gpiod_line_free(line);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }

            // Read the distance
            if ((distance = gpiod_line_get_value(line)) < 0) {
                perror("gpiod_line_get_value");
                gpiod_line_free(line);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }

            // Print the distance
            printf("Distance: %d cm\n", distance);
        }

        // Sleep for 1 second
        if (usleep(1000000) < 0) {
            perror("usleep");
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        count++;
        if (count > 10) {
            break;
        }
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

