    if ((line = gpiod_chip_get_line(chip, 23)) == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Create a loop to read the edge
    if ((loop = gpiod_edge_create_loop(edge, GPIOD_EDGE_BOTH, GPIOD_LOOP_NOWAIT)) == NULL) {
        perror("gpiod_edge_create_loop");
        goto cleanup;
    }

    // Set the loop to run indefinitely
    if (gpiod_loop_set_period(loop, 100000000) < 0) {
        perror("gpiod_loop_set_period");
        goto cleanup;
