#include <stdlib.h>
#include <gpiod.h>

int main() {
    int err;

    // Open the GPIO subsystem
    err = gpiod_open("/dev/gpiod");
    if (err < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Create a new GPIO instance
    err = gpiod_request_new(17, GPIO_EDGE_FALLING, GPIO_MODE_OUTPUT);
    if (err < 0) {
        perror("gpiod_request_new");
        gpiod_release();
        return 1;
    }

    // Get the GPIO instance
    gpiod_gpio_t *gpio = gpiod_request_get();

    // Set the direction to output
    err = gpiod_gpio_set_direction(gpio, GPIO_DIR_OUTPUT);
    if (err < 0) {
        perror("gpiod_gpio_set_direction");
        gpiod_release();
        return 1;
    }

    // Set the value to 0 (low)
    err = gpiod_gpio_set_value(gpio, 0);
    if (err < 0) {
        perror("gpiod_gpio_set_value");
        gpiod_release();
        return 1;
    }

    printf("Output set to low\n");

    // Release the GPIO instance
    gpiod_release(gpio);

    // Close the GPIO subsystem
    err = gpiod_close();
    if (err < 0) {
        perror("gpiod_close");
        return 1;
    }

    return 0;
}

