    struct gpiod_edge *edge;
    struct gpiod_loop *loop;
    struct gpiod_loop_state state;
    int value = 1; // Start with output high

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 2)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the line to output high
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Create a loop for the line
    if ((loop = gpiod_loop_new(line)) == NULL) {
        perror("gpiod_loop_new");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the loop to trigger on edge
    if (gpiod_loop_set_edge(loop, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_loop_set_edge");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the loop to trigger on both rising and falling edges
    if (gpiod_loop_set_edge(loop, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_loop_set_edge");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the loop to trigger on both rising and falling edges
    if (gpiod_loop_set_edge(loop, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_loop_set_edge");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Start the loop
    if (gpiod_loop_start(loop) < 0) {
        perror("gpiod_loop_start");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        sleep(5);
        printf("Cycle %d: Output %d\n", i + 1, value);
    }

    // Stop the loop
    if (gpiod_loop_stop(loop) < 0) {
        perror("gpiod_loop_stop");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Close the loop
    if (gpiod_loop_close(loop) < 0) {
        perror("gpiod_loop_close");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Close the line
    if (gpiod_line_close(line) < 0) {
        perror("gpiod_line_close");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Close the chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Close the GPIO device
    if (gpiod_close(fd) < 0) {
        perror("gpiod_close");
        exit(EXIT_FAILURE);
    }

    return 0;
}

