            goto cleanup;
        }

        // Print the state
        printf("State: 0\n");
    }

cleanup:
    // Release the hardware
    if (gpiod_loop_stop(loop)) {
        perror("gpiod_loop_stop");
    }
    if (gpiod_line_put_edge(edge)) {
        perror("gpiod_line_put_edge");
    }
    if (gpiod_line_put_loop(loop)) {
        perror("gpiod_line_put_loop");
    }
    if (gpiod_chip_put(chip)) {
