        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_type(chip, line, &line->type) < 0) {
        perror("gpiod_chip_get_line_type");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (line->type != GPIOD_LINE_TYPE_EDGE) {
        fprintf(stderr, "GPIO must be an edge GPIO\n");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_edge(chip, line, &edge) < 0) {
        perror("gpiod_chip_get_line_edge");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (edge->direction != GPIOD_EDGE_DIR_INPUT) {
        fprintf(stderr, "GPIO must be in input mode\n");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_loop(chip, line, &loop) < 0) {
        perror("gpiod_chip_get_line_loop");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

