        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_loop_free(loop);
        gpiod_close(fd);
        return 1;
    }

    int state = 0;
    while (1) {
        if (gpiod_loop_poll(loop) < 0) {
            perror("gpiod_loop_poll");
            gpiod_loop_free(loop);
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            gpiod_close(fd);
            return 1;
        }

        if (state) {
            gpiod_line_set_value(line, 0);
