        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 18)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge loop
    if ((loop = gpiod_loop_new(chip, line)) == NULL) {
        perror("gpiod_loop_new");
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high (1)
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge loop
    if ((edge = gpiod_loop_get_edge(loop, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_loop_get_edge");
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Set the edge loop to trigger on both rising and falling edges
    if (gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_edge_set_edge");
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Set the edge loop to trigger on both rising and falling edges
    if (gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_edge_set_edge");
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Start the edge loop
    if (gpiod_loop_start(loop) < 0) {
        perror("gpiod_loop_start");
        gpiod_edge_close(edge);
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Sleep for 0.1 seconds
    usleep(100000);

    // Stop the edge loop
    if (gpiod_loop_stop(loop) < 0) {
        perror("gpiod_loop_stop");
        gpiod_edge_close(edge);
        gpiod_loop_close(loop);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_close(fd);
        return 1;
    }

    // Release the hardware
    gpiod_chip_close(chip);
    gpiod_line_close(line);
    gpiod_loop_close(loop);
    gpiod_close(fd);

    printf("State applied: HIGH\n");
    return 0;
}

