int main() {
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    chip = gpiod_chip_open("/dev/gpiod");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Find the GPIO line
    line = gpiod_chip_get_line(chip, 2);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create an edge
    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create a loop
    loop = gpiod_edge_create_loop(edge);
    if (loop == NULL) {
        perror("gpiod_edge_create_loop");
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the loop to run
    gpiod_loop_start(loop);
    if (gpiod_loop_status(loop) == GPIOD_LOOP_STOPPED) {
        gpiod_loop_stop(loop);
    }

    // Print initial state
    printf("Initial state: %d\n", gpiod_line_get_value(line));

    // Run the loop
    while (1) {
        // Wait for 0.05 seconds
        err = gpiod_loop_wait(loop, 50000000); // 50ms
        if (err) {
            perror("gpiod_loop_wait");
            gpiod_loop_free(loop);
            gpiod_edge_free(edge);
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Toggle the state
        gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
        gpiod_line_set_value(line, 1 - gpiod_line_get_value(line));
        printf("State toggled: %d\n", gpiod_line_get_value(line));

        // Wait for 0.05 seconds
        err = gpiod_loop_wait(loop, 50000000); // 50ms
        if (err) {
