int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int direction;
    int state;

    fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_list_lines(chip, &line, NULL) < 0) {
        perror("gpiod_chip_list_lines");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (line->number != 18) {
        fprintf(stderr, "GPIO 18 not found\n");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_direction(chip, line, &direction) < 0) {
        perror("gpiod_chip_get_direction");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (direction == GPIOD_EDGE_BOTH) {
        fprintf(stderr, "GPIO 18 is in edge mode, cannot set direction\n");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (direction == GPIOD_EDGE_UP) {
        direction = GPIOD_EDGE_DOWN;
    } else if (direction == GPIOD_EDGE_DOWN) {
        direction = GPIOD_EDGE_UP;
    }

    if (gpiod_chip_request_direction(chip, line, direction) < 0) {
        perror("gpiod_chip_request_direction");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_request_line(chip, line, GPIOD_EDGE_NONE) < 0) {
        perror("gpiod_chip_request_line");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    state = 0;
    if (gpiod_line_set_value(line, state) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    fprintf(stderr, "GPIO 18 set to %d\n", state);

    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

