#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x44
#define OPT3001_REG_ADDR 0x00
#define OPT3001_REG_MEAS 0x01

int main() {
    int fd;
    uint8_t data[2];
    uint16_t value;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    while (1) {
        data[0] = OPT3001_REG_ADDR;
        data[1] = 0;
        if (write(fd, data, 2) != 2) {
            perror("write");
            close(fd);
            return 1;
        }

        if (read(fd, data, 2) != 2) {
            perror("read");
            close(fd);
            return 1;
        }

        value = (data[0] << 8) | data[1];
        printf("Measurement: %u\n", value);

        // Release the hardware on exit
        if (close(fd)) {
            perror("close");
            return 1;
        }
    }

    return 0;
}

