#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define HTU21D_REG_TEMP 0x40
#define HTU21D_REG_HUMID 0x41

int i2c_fd;

void i2c_init() {
    i2c_fd = open("/dev/i2c-dev", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_data(int reg) {
    char buffer[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    int temp = (buffer[0] << 8) | buffer[1];
    int humidity = (buffer[0] << 8) | buffer[1];

    if (temp < 0x8000 || temp > 0xB83F) {
        printf("Invalid temperature reading: %d\n", temp);
        return;
    }

    if (humidity < 0x8000 || humidity > 0xD23F) {
        printf("Invalid humidity reading: %d\n", humidity);
        return;
    }

    int temp_c = (temp - 0x3080) / 0x80;
    int humidity_percent = (humidity - 0x3080) / 0x80;

    printf("Temperature: %d.%02d C\n", temp_c, (temp_c * 100 + (temp % 0x80)) / 0x80);
    printf("Humidity: %d.%02d%%\n", humidity_percent, (humidity_percent * 100 + (humidity % 0x80)) / 0x80);
}

void i2c_loop() {
    while (1) {
        i2c_read_data(HTU21D_REG_TEMP);
        i2c_read_data(HTU21D_REG_HUMID);
        sleep(60);
    }
}

int main() {
    i2c_init();
    i2c_loop();

    close(i2c_fd);
    return 0;
}

