#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_XYZ 0x00

int i2c_fd;

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }
}

void read_adxl345() {
    char buffer[2];
    ssize_t bytes_read;

    buffer[0] = ADXL345_REG_XYZ;
    buffer[1] = 0;

    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to ADXL345");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from ADXL345");
        exit(EXIT_FAILURE);
    }

    int x = (int)(buffer[0] << 8 | buffer[1]);
    int y = (int)(buffer[0] << 8 | buffer[1]);
    int z = (int)(buffer[0] << 8 | buffer[1]);

    printf("%d %d %d\n", x, y, z);
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    init_i2c();

    while (1) {
        read_adxl345();
        sleep(0.1);
    }

    cleanup();

    return 0;
}

