void handle_error(int err, const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void cleanup() {
    // Release the camera device
    if (camera_fd != -1) {
        close(camera_fd);
    }
    // Release the image buffer
    if (image_buffer != NULL) {
        munmap(image_buffer, image_size);
    }
    // Release the image file
    if (image_file_fd != -1) {
        close(image_file_fd);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    // Open the camera device
    camera_fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (camera_fd == -1) {
        handle_error("open", "camera device");
    }

    // Set the camera parameters
    struct v4l2_capability cap;
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        handle_error("VIDIOC_QUERYCAP", "camera capabilities");
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        handle_error("V4L2_CAP_VIDEO_CAPTURE", "camera is not a video capture device");
    }

    struct v4l2_format fmt;
    fmt.type = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        handle_error("VIDIOC_S_FMT", "set image format");
    }

    // Allocate memory for the image buffer
    image_size = fmt.fmt.pix.width * fmt.fmt.pix.height * 2;
    image_buffer = mmap(0, image_size, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (image_buffer == MAP_FAILED) {
        handle_error("mmap", "allocate image buffer");
    }

    // Capture the image
    if (ioctl(camera_fd, VIDIOC_G_TOPOBASE, &top_base) < 0) {
        handle_error("VIDIOC_G_TOPOBASE", "get top base");
    }
    if (ioctl(camera_fd, VIDIOC_READ, &top_base) < 0) {
        handle_error("VIDIOC_READ", "read image");
    }

    // Write the image to the file
    image_file_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (image_file_fd == -1) {
        handle_error("open", "image file");
    }
    if (write(image_file_fd, image_buffer, image_size) != image_size) {
        handle_error("write", "write image to file");
    }
    close(image_file_fd);

    cleanup();

    return 0;
}

