int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int state;

    fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_list_lines(chip, &line, NULL) < 0) {
        perror("gpiod_chip_list_lines");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (line->number != 2 && line->number != 3 && line->number != 5) {
        fprintf(stderr, "Invalid GPIO number\n");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_direction(chip, line, &state) < 0) {
        perror("gpiod_chip_get_line_direction");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (state == GPIOD_EDGE_BOTH) {
        fprintf(stderr, "GPIO %d is both input and output\n", line->number);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_request_line(chip, line, GPIOD_EDGE_BOTH, &edge) < 0) {
        perror("gpiod_chip_request_line");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(edge, 1);
        fprintf(stderr, "Outputting to GPIO %d\n", line->number);
        fflush(stderr);
        usleep(5000000); // 5 seconds

        gpiod_line_set_value(edge, 0);
        fprintf(stderr, "Turning off GPIO %d\n", line->number);
        fflush(stderr);
        usleep(5000000); // 5 seconds
    }

    gpiod_chip_free(chip);
    gpiod_close(fd);
    return 0;
}

