    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 17)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high (1)
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the edge to rising
    if (gpiod_edge_set_edge(edge, GPIOD_EDGE_RISING) < 0) {
        perror("gpiod_edge_set_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Start the edge
    if (gpiod_edge_start(edge) < 0) {
        perror("gpiod_edge_start");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        // Wait for an interrupt
        if (gpiod_edge_wait(edge) < 0) {
            perror("gpiod_edge_wait");
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        // Read the distance
        int distance = 0;
        if ((distance = hc_sr04_read_distance(17)) == -1) {
            perror("hc_sr04_read_distance");
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        // Print the distance
        printf("Distance: %d cm\n", distance);

        // Wait for 0.2 seconds
        if (sleep(0.2) < 0) {
            perror("sleep");
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        count++;
        if (count % 10 == 0) {
            printf("Count: %d\n", count);
        }
    }

    // Cleanup
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

int hc_sr04_read_distance(int pin) {
    int distance = -1;
