#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x76
#define BME280_REG_MEASUREMENT 0xF2

int main() {
    int fd;
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    char buf[8];
    int err;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        close(fd);
        return 1;
    }

    memset(&rdwr_msg, 0, sizeof(rdwr_msg));
    rdwr_msg.msg_length = 2;
    rdwr_msg.msgs = msg;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 1;
    msg[0].buf = &buf[0];

    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 7;
    msg[1].buf = buf;

    if (ioctl(fd, I2C_RDWR, &rdwr_msg) < 0) {
        perror("Failed to send i2c message");
        close(fd);
        return 1;
    }

    if (buf[0] == 0x80) {
        printf("BME280 not found\n");
        close(fd);
        return 1;
    }

    while (1) {
        if (read(fd, buf, 8) != 8) {
            perror("Failed to read i2c data");
            close(fd);
            return 1;
        }

        if (buf[0] == 0x80) {
            printf("BME280 not found\n");
            close(fd);
            return 1;
        }

        printf("Temperature: %.2f°C, Pressure: %.2f hPa, Humidity: %.2f%%\n",
               (buf[2] << 8 | buf[3]) / 10.0,
               (buf[4] << 16 | buf[5] << 8 | buf[6]) / 100.0,
               (buf[0] << 8 | buf[1]) / 256.0);

        sleep(5);
    }

    close(fd);
    return 0;
}

