    }

    // Set direction to output
    err = gpiod_set_direction(gpio, GPIODIRECTION_OUTPUT);
    if (err < 0) {
        perror("gpiod_set_direction");
        gpiod_close(gpio);
        exit(1);
    }

    // Set value to 1 (high)
    err = gpiod_set_value(gpio, value);
    if (err < 0) {
        perror("gpiod_set_value");
        gpiod_close(gpio);
        exit(1);
    }

    // Print the state
    printf("Output set to 1\n");

    // Sleep for 60 seconds
    sleep(60);

    // Repeat the loop
    while (1) {
        // Toggle the state
        value = !value;
        err = gpiod_set_value(gpio, value);
        if (err < 0) {
            perror("gpiod_set_value");
            gpiod_close(gpio);
            exit(1);
        }

        // Print the new state
        printf("Output set to %d\n", value);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up on exit
    gpiod_close(gpio);
    return 0;
}

