    if (gpiod_chip_get_line_direction(chip, line, &line->direction) < 0) {
        perror("gpiod_chip_get_line_direction");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (line->direction != GPIOD_EDGE_BOTH) {
        fprintf(stderr, "GPIO 23 is not a digital output\n");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_number(chip, line, &line->number) < 0) {
        perror("gpiod_chip_get_line_number");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    if (line->number != 23) {
        fprintf(stderr, "GPIO 23 not found\n");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    line->direction = GPIOD_EDGE_BOTH;
    if (gpiod_chip_request_line(chip, line, 0, 0) < 0) {
        perror("gpiod_chip_request_line");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    loop = gpiod_loop_new(chip, GPIOD_LOOP_EDGE_BOTH);
    if (!loop) {
        perror("gpiod_loop_new");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    edge = gpiod_loop_request_edge(loop, GPIOD_EDGE_BOTH, 0);
    if (!edge) {
        perror("gpiod_loop_request_edge");
        gpiod_loop_free(loop);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        gpiod_edge_set_direction(edge, GPIOD_EDGE_BOTH);
        gpiod_edge_set_value(edge, 1);
        printf("Output set to 1\n");
        fflush(stdout);
        sleep(0.05);

        gpiod_edge_set_direction(edge, GPIOD_EDGE_BOTH);
        gpiod_edge_set_value(edge, 0);
        printf("Output set to 0\n");
        fflush(stdout);
        sleep(0.05);
    }

    gpiod_loop_free(loop);
    gpiod_chip_free(chip);
    gpiod_line_free(line);
    gpiod_close(fd);
    return 0;
}

