    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO device: %s\n", gpiod_chip_strerror(err));
        return 1;
    }

    // Create a new line for GPIO 14
    line = gpiod_chip_new_line(chip, GPIO14, GPIOD_LINE_DIR_OUT);
    if (line == NULL) {
        fprintf(stderr, "Error creating GPIO line: %s\n", gpiod_line_strerror(err));
        gpiod_chip_close(chip);
        return 1;
    }

    // Create an edge for the line
    edge = gpiod_line_new_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        fprintf(stderr, "Error creating edge: %s\n", gpiod_edge_strerror(err));
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
