        fflush(stdout);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Exit cleanly
    gpiod_loop_stop(loop);
    gpiod_edge_free(edge);
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    return 0;
}

