int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Get the first chip
    if ((chip = gpiod_chip_from_fd(fd)) == NULL) {
        perror("gpiod_chip_from_fd");
        goto cleanup;
    }

    // Find the GPIO 23 line
    if ((line = gpiod_chip_get_line(chip, 23)) == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create a loop for the line
    if ((loop = gpiod_loop_from_line(line)) == NULL) {
        perror("gpiod_loop_from_line");
        goto cleanup;
    }

    // Create an edge for the loop
    if ((edge = gpiod_loop_get_edge(loop, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_loop_get_edge");
        goto cleanup;
    }

    // Set the edge to rising
    if (gpiod_edge_set_mode(edge, GPIOD_MODE_EDGE_RISING) < 0) {
        perror("gpiod_edge_set_mode");
        goto cleanup;
    }

    // Start the loop
    if (gpiod_loop_start(loop) < 0) {
        perror("gpiod_loop_start");
        goto cleanup;
    }

    // Print the initial state
    printf("Initial state: %s\n", gpiod_line_get_value(line) ? "High" : "Low");

    // Main loop
    while (1) {
        // Wait for 5 seconds
        if (sleep(5) < 0) {
            perror("sleep");
            goto cleanup;
        }

        // Print the current state
        printf("State: %s\n", gpiod_line_get_value(line) ? "High" : "Low");
    }

cleanup:
    // Release resources
    if (edge) gpiod_edge_free(edge);
    if (loop) gpiod_loop_free(loop);
    if (line) gpiod_line_free(line);
    if (chip) gpiod_chip_free(chip);
    if (fd) gpiod_close(fd);

    return EXIT_SUCCESS;
}

