#define GPIO17 17
#define GPIO22 22
#define GPIO27 27

#define MAX_DISTANCE 4000
#define MIN_DISTANCE 10

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;
    struct gpiod_event *event;
    int distance;
    int count = 0;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the chip
    if ((chip = gpiod_chip_from_fd(fd)) == NULL) {
        perror("gpiod_chip_from_fd");
        return 1;
    }

    // Create a line for GPIO 17
    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        return 1;
    }

    // Create a loop for the edge
    if ((loop = gpiod_edge_create_loop(edge)) == NULL) {
        perror("gpiod_edge_create_loop");
        return 1;
    }

    // Create an event for the loop
    if ((event = gpiod_loop_request_event(loop, GPIOD_EDGE_BOTH, 0)) == NULL) {
        perror("gpiod_loop_request_event");
        return 1;
    }

    // Set the event to trigger on both edges
    if (gpiod_event_set_edge(event, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_event_set_edge");
        return 1;
    }

    // Start the loop
    if (gpiod_loop_start(loop) < 0) {
        perror("gpiod_loop_start");
        return 1;
    }

    // Initialize the distance counter
    distance = 0;

    // Main loop
    while (1) {
        // Wait for an event
        if (gpiod_loop_wait_event(loop, event) < 0) {
            perror("gpiod_loop_wait_event");
            return 1;
        }

        // Read the line value
        if (gpiod_line_get_value(line, &distance) < 0) {
            perror("gpiod_line_get_value");
            return 1;
        }

        // Check if the distance is valid
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid distance: %d\n", distance);
            continue;
        }

        // Print the distance
        printf("Distance: %d cm\n", distance);

        // Increment the counter
        count++;

        // Check if we've reached the maximum number of readings
        if (count >= 10) {
            count = 0;
        }
    }

    // Clean up resources
    gpiod_loop_destroy(loop);
    gpiod_event_free(event);
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

