#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int state;
    int distance;
    double start_time, end_time;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_PIN_23)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_close(fd);
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an event for the edge
    if ((event = gpiod_edge_request_event(edge, GPIOD_EDGE_BOTH, 0)) == NULL) {
        perror("gpiod_edge_request_event");
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Start the event
    if (gpiod_event_start(event) < 0) {
        perror("gpiod_event_start");
        gpiod_event_free(event);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    start_time = time(NULL);

    while (1) {
        if (gpiod_event_pending(event)) {
            if (gpiod_event_read(event, &state) < 0) {
                perror("gpiod_event_read");
                gpiod_event_free(event);
                gpiod_edge_free(edge);
                gpiod_line_free(line);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }

            if (state == 1) {
                // Start timing
                start_time = time(NULL);
            } else if (state == 0) {
                // Stop timing
                end_time = time(NULL);
                distance = 17150000.0 * (end_time - start_time) / 1000000.0;
                printf("Distance: %.2f cm\n", distance);
            }
        }

        // Sleep for 0.2 seconds
        if (sleep(0.2) < 0) {
            perror("sleep");
            gpiod_event_free(event);
            gpiod_edge_free(edge);
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }
    }

    // Clean up resources
    gpiod_event_free(event);
    gpiod_edge_free(edge);
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

