#define BMP280_ADDR 0x76
#define BMP280_REG_CONTROL 0xF0
#define BMP280_REG_TEMP_MSB 0xF3
#define BMP280_REG_TEMP_LSB 0xF4
#define BMP280_REG_PRESS_MSB 0xF5
#define BMP280_REG_PRESS_LSB 0xF6

int bmp280_fd = -1;

void bmp280_init() {
    if ((bmp280_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(bmp280_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set slave address");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }
}

void bmp280_read() {
    uint8_t buf[2];
    int err;

    // Set control register
    buf[0] = BMP280_REG_CONTROL;
    buf[1] = 0x36; // Normal mode, oversampling
    err = ioctl(bmp280_fd, I2C_RDWR, buf);
    if (err < 0) {
        perror("Failed to set control register");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }

    // Read temperature MSB and LSB
    buf[0] = BMP280_REG_TEMP_MSB;
    err = ioctl(bmp280_fd, I2C_RDWR, buf);
    if (err < 0) {
        perror("Failed to read temperature MSB");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }
    buf[0] = BMP280_REG_TEMP_LSB;
    err = ioctl(bmp280_fd, I2C_RDWR, buf);
    if (err < 0) {
        perror("Failed to read temperature LSB");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }

    // Read pressure MSB and LSB
    buf[0] = BMP280_REG_PRESS_MSB;
    err = ioctl(bmp280_fd, I2C_RDWR, buf);
    if (err < 0) {
        perror("Failed to read pressure MSB");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }
    buf[0] = BMP280_REG_PRESS_LSB;
    err = ioctl(bmp280_fd, I2C_RDWR, buf);
    if (err < 0) {
        perror("Failed to read pressure LSB");
        close(bmp280_fd);
        exit(EXIT_FAILURE);
    }

    // Convert to temperature and pressure
    int16_t temp_msb = buf[0] << 8 | buf[1];
    int16_t temp_lsb = buf[2] << 8 | buf[3];
    float temp = (temp_msb + temp_lsb) / 16384.0;

    int16_t press_msb = buf[4] << 8 | buf[5];
    int16_t press_lsb = buf[6] << 8 | buf[7];
    float press = (press_msb + press_lsb) / 16384.0;

    printf("%.2f,%.2f\n", temp, press);
}

void bmp280_loop() {
    bmp280_init();
    while (1) {
        bmp280_read();
        sleep(5);
    }
}

int main() {
    bmp280_loop();
    return 0;
}

