void mqtt_callback(struct mosquitto *mosq, void *userdata, int msg);

int main() {
    struct mosquitto *mosq;
    mosquitto_options_t options;
    mosquitto_subscribe_t *sub;

    if ((mosq = mosquitto_new(NULL, true, NULL)) == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return 1;
    }

    options.keepalive = 60;
    mosquitto_set_options(mosq, &options);

    sub = malloc(sizeof(mosquitto_subscribe_t));
    sub->topic = strdup(MQTT_TOPIC);
    sub->qos = mqtt_qos;
    mosquitto_subscribe(mosq, sub);

    if ((mqtt_client = mosquitto_new_publish_callback(mosq, mqtt_callback, NULL)) == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return 1;
    }

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 0) < 0) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        return 1;
    }

    signal(SIGINT, [](int) {
        if (mosquitto_destroy(mosq) == MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "MQTT client destroyed\n");
        }
        if (mqtt_client) {
            if (mosquitto_destroy(mqtt_client) == MOSQ_ERR_SUCCESS) {
                fprintf(stderr, "MQTT client destroyed\n");
            }
        }
        free(sub);
        free(mosq);
        return 0;
    });

    if (fork() == 0) {
        // Child process
        if (execl("/usr/bin/mosquitto_pub", "mosquitto_pub", "-h", MQTT_HOST, "-p", MQTT_PORT, "-t", MQTT_TOPIC, NULL) == -1) {
            perror("execl");
            return 1;
        }
    } else {
        // Parent process
        if (waitpid(-1, NULL, 0) == -1) {
            perror("waitpid");
            return 1;
        }
    }

    return 0;
}

void mqtt_callback(struct mosquitto *mosq, void *userdata, int msg) {
    if (msg == MOSQ_ERR_CONNECTED) {
        fprintf(stderr, "Connected to MQTT broker\n");
    } else if (msg == MOSQ_ERR_CONNECT) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
    } else if (msg == MOSQ_ERR_SUBSCRIBE) {
        fprintf(stderr, "Failed to subscribe to MQTT topic\n");
    } else if (msg == MOSQ_ERR_PUBLISH) {
        fprintf(stderr, "Failed to publish MQTT message\n");
    } else if (msg == MOSQ_ERR_QOS) {
        fprintf(stderr, "Failed to set MQTT QoS\n");
    } else if (msg == MOSQ_ERR_TOPIC) {
        fprintf(stderr, "Failed to set MQTT topic\n");
    } else if (msg == MOSQ_ERR_PAYLOAD) {
        fprintf(stderr, "Failed to set MQTT payload\n");
    } else if (msg == MOSQ_ERR_DATA) {
        fprintf(stderr, "Failed to receive MQTT data\n");
    } else if (msg == MOSQ_ERR_CALLBACK) {
        fprintf(stderr, "Failed to set MQTT callback\n");
    } else if (msg == MOSQ_ERR_UNKNOWN) {
        fprintf(stderr, "Unknown MQTT error\n");
    } else {
        fprintf(stderr, "MQTT callback error: %d\n", msg);
    }
}

