    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        error = 1;
    }

    // Set PWM frequency to 50Hz for all GPIOs
    if (gpioSetClockDivider(50) < 0) {
        perror("gpioSetClockDivider");
        error = 1;
    }

    // Set PWM duty cycle to 0% for all GPIOs
    if (gpioSetPWMfreq(50) < 0) {
        perror("gpioSetPWMfreq");
        error = 1;
    }

    // Set PWM duty cycle to 0% for all GPIOs
    if (gpioSetPWMdutycycle(2, 0) < 0) {
        perror("gpioSetPWMdutycycle");
        error = 1;
    }
    if (gpioSetPWMdutycycle(3, 0) < 0) {
        perror("gpioSetPWMdutycycle");
        error = 1;
    }
    if (gpioSetPWMdutycycle(18, 0) < 0) {
        perror("gpioSetPWMdutycycle");
        error = 1;
    }
    if (gpioSetPWMdutycycle(23, 0) < 0) {
        perror("gpioSetPWMdutycycle");
        error = 1;
    }
    if (gpioSetPWMdutycycle(24, 0) < 0) {
        perror("gpioSetPWMdutycycle");
        error = 1;
    }

    // Report the state applied to standard output
    printf("PWM output state set to 0% duty cycle for all GPIOs\n");

    // Release resources on exit
    atexit(gpioTerminate);

    // Run until interrupted
    while (1) {
        sleep(1);
    }

    return error;
}

