#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/v4l2.h>
#include <libgpiod.h>

#define IMAGE_WIDTH 2592
#define IMAGE_HEIGHT 1944
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

int main() {
    int camera_fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_image_plane_info plane_info;
    struct v4l2_control control;
    int plane = 0;
    int ret;

    // Open camera device
    camera_fd = open("/dev/video0", O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Get camera capabilities
    ret = ioctl(camera_fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query camera capabilities");
        close(camera_fd);
        return 1;
    }

    // Set image format
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.colorspace = V4L2_COLORSPACE_SRGB;

    ret = ioctl(camera_fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set image format");
        close(camera_fd);
        return 1;
    }

    // Set image plane
    plane_info.plane_type = V4L2_IMAGE_PLANE_TYPE_MONO8;
    plane_info.plane_index = plane;
    ret = ioctl(camera_fd, VIDIOC_S_IMAGE, &plane_info);
    if (ret < 0) {
        perror("Failed to set image plane");
        close(camera_fd);
        return 1;
    }

    // Capture image
    ret = ioctl(camera_fd, VIDIOC_G_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to get image format");
        close(camera_fd);
        return 1;
    }

    unsigned char *image_buffer = malloc(fmt.fmt.pix.width * fmt.fmt.pix.height * fmt.fmt.pix.elem_size);
    if (!image_buffer) {
        perror("Failed to allocate image buffer");
        close(camera_fd);
        return 1;
    }

    ret = ioctl(camera_fd, VIDIOC_G_PARM, &control, (void *)&fmt);
    if (ret < 0) {
        perror("Failed to get image parameters");
        free(image_buffer);
        close(camera_fd);
        return 1;
    }

    ret = ioctl(camera_fd, VIDIOC_G_STREAMCTRL, &control);
    if (ret < 0) {
        perror("Failed to get stream control parameters");
        free(image_buffer);
        close(camera_fd);
        return 1;
    }

    ret = ioctl(camera_fd, VIDIOC_G_SUBDEV, &plane_info);
    if (ret < 0) {
        perror("Failed to get subdevice parameters");
        free(image_buffer);
        close(camera_fd);
        return 1;
    }

    ret = ioctl(camera_fd, VIDIOC_G_PARM, &control, (void *)&plane_info);
    if (ret < 0) {
        perror("Failed to get subdevice parameters");
        free(image_buffer);
        close(camera_fd);
