#define UART_DEV "/dev/ttyAMA0"
#define BAUD_RATE 115200

int fd;
struct termios oldtio, newtio;

void setup_serial() {
    if ((fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_NONBLOCK)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    tcgetattr(fd, &oldtio);
    newtio.c_cflag |= BAUDRATE | CS8 | CLOCAL | CSTOPB;
    newtio.c_iflag |= IGNBRK | ICRNL;
    newtio.c_lflag = 0;
    newtio.c_oflag = 0;
    newtio.c_cc[VTIME] = 0;
    newtio.c_cc[VMIN] = 1;

    if (tcsetattr(fd, TCSANOW, &newtio) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

void cleanup_serial() {
    tcsetattr(fd, TCSANOW, &oldtio);
    close(fd);
}

void signal_handler(int signum) {
    cleanup_serial();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_serial();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("read");
            cleanup_serial();
            exit(EXIT_FAILURE);
        } else if (bytes_read == 0) {
            continue;
        } else {
            printf("%s\n", buffer);
        }
    }

    return 0;
}

