    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return EXIT_FAILURE;
    }

    gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    edge = gpiod_line_get_edge(line);
    if (!edge) {
        perror("gpiod_line_get_edge");
        gpiod_chip_close(chip);
        gpiod_line_unref(line);
        gpiod_close(fd);
        return EXIT_FAILURE;
    }

    gpiod_loop_init(loop, edge);
    if (!loop) {
        perror("gpiod_loop_init");
        gpiod_chip_close(chip);
        gpiod_line_unref(line);
        gpiod_edge_unref(edge);
        gpiod_close(fd);
        return EXIT_FAILURE;
    }

    gpiod_loop_start(loop);
    if (gpiod_loop_wait(loop) != 0) {
        perror("gpiod_loop_wait");
        gpiod_loop_destroy(loop);
        gpiod_chip_close(chip);
        gpiod_line_unref(line);
        gpiod_edge_unref(edge);
        gpiod_close(fd);
        return EXIT_FAILURE;
    }

    gpiod_loop_destroy(loop);
    gpiod_chip_close(chip);
    gpiod_line_unref(line);
    gpiod_edge_unref(edge);
    gpiod_close(fd);

    printf("State applied: %s\n", gpiod_line_get_value(line) ? "High" : "Low");
    return EXIT_SUCCESS;
}

