#define DHT22_PIN 4

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int value;
    int count = 0;
    int max_retries = 5;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        goto cleanup;
    }

    // Find the DHT22 pin
    if ((line = gpiod_chip_get_line(chip, DHT22_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Start the edge
    if (gpiod_edge_start(edge)) {
        perror("gpiod_edge_start");
        goto cleanup;
    }

    while (count < max_retries) {
        // Read the value
        if (gpiod_line_request_value(line, &value)) {
            perror("gpiod_line_request_value");
            goto cleanup;
        }

        // Check if the reading is valid
        if (value == 0) {
            // DHT22 is not ready, try again
            count++;
            continue;
        }

        // Check if the reading is valid
        if (value == 1) {
            // DHT22 is ready, read the humidity and temperature
            if (gpiod_line_request_value(line, &value)) {
                perror("gpiod_line_request_value");
                goto cleanup;
            }

            if (value == 0) {
                // Temperature reading failed
                count++;
                continue;
            }

            if (gpiod_line_request_value(line, &value)) {
                perror("gpiod_line_request_value");
                goto cleanup;
            }

            if (value == 0) {
                // Humidity reading failed
                count++;
                continue;
            }

            // Valid reading, print the result
            printf("Temperature: %d.%02d C\n", value / 10, value % 10);
            printf("Humidity: %d.%02d %%\n", value / 10, value % 10);
            break;
        }

        // Invalid reading, try again
        count++;
    }

    // Stop the edge
    if (gpiod_edge_stop(edge)) {
        perror("gpiod_edge_stop");
    }

    // Release the line
    if (gpiod_line_free(edge)) {
        perror("gpiod_line_free");
    }

    // Release the chip
    if (gpiod_chip_free(chip)) {
        perror("gpiod_chip_free");
    }

    // Close the GPIO device
    if (gpiod_close(fd)) {
        perror("gpiod_close");
    }

    return 0;

cleanup:
    // Release the line
    if (gpiod_line_free(edge)) {
        perror("gpiod_line_free");
    }

    // Release the chip
    if (gpiod_chip_free(chip)) {
        perror("gpiod_chip_free");
    }

    // Close the GPIO device
    if (gpiod_close(fd)) {
        perror("gpiod_close");
    }

    return 1;
}

