#define MCP3008_ADDR 0x68
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023

int adc_fd;
int mqtt_client;
int mqtt_qos;
int mqtt_topic[2];
int mqtt_port;
int mqtt_keepalive;
int mqtt_publish_count;
int mqtt_last_publish_time;
int mqtt_last_publish_value;
int mqtt_last_publish_channel;

void cleanup() {
    if (adc_fd > 0) {
        close(adc_fd);
    }
    if (mqtt_client > 0) {
        paho_mqtt2_destroy(mqtt_client);
    }
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int init_mcp3008() {
    adc_fd = open("/dev/i2c-" i2c_get_id(), O_RDWR);
    if (adc_fd < 0) {
        perror("Failed to open i2c device");
        return -1;
    }

    if (ioctl(adc_fd, I2C_SLAVE, MCP3008_ADDR) < 0) {
        perror("Failed to set i2c slave address");
        return -1;
    }

    return 0;
}

int init_mqtt() {
    struct paho_mqtt_options options;
    options.keepalive = 60;
    options.qos = 1;
    options.topic = "sensor_readings";
    options.username = "mqtt_user";
    options.password = "mqtt_password";

    mqtt_client = paho_mqtt2_new(&options);
    if (mqtt_client == NULL) {
        perror("Failed to create MQTT client");
        return -1;
    }

    return 0;
}

int publish_mqtt() {
    int value = read_adc();
    if (value < 0) {
        return -1;
    }

    time_t now = time(NULL);
    if (now < 0) {
        return -1;
    }

    if (mqtt_publish_count == 0) {
        mqtt_publish_count = 1;
    }

    if (now - mqtt_last_publish_time > 1000) {
        mqtt_last_publish_time = now;
        mqtt_last_publish_value = value;
        mqtt_last_publish_channel = ADC_CHANNEL;
        if (paho_mqtt2_publish(mqtt_client, "sensor_readings", NULL, 0, NULL, 0, &value) < 0) {
            return -1;
        }
    } else {
        if (value != mqtt_last_publish_value || ADC_CHANNEL != mqtt_last_publish_channel) {
            if (paho_mqtt2_publish(mqtt_client, "sensor_readings", NULL, 0, NULL, 0, &value) < 0) {
                return -1;
            }
        }
    }

    return 0;
}

int read_adc() {
    int buffer[3];
    if (ioctl(adc_fd, I2C_SAMP, 0) < 0) {
        perror("Failed to start ADC conversion");
        return -1;
    }

    if (read(adc_fd, buffer, 3) < 0) {
        perror("Failed to read ADC data");
        return -1;
    }

    int value = (buffer[1] << 8) | buffer[2];
    if (value > ADC_MAX_VALUE) {
        value = ADC_MAX_VALUE;
    }

    return value;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    signal(SIGABRT, handle_signal);
    signal(SIGFPE, handle_signal);
    signal(SIGILL, handle_signal);
    signal(SIGSEGV, handle_signal);
    signal(SIGBUS, handle_signal);
    signal(SIGPIPE, SIG_IGN);

    if (init_mcp3008() < 0) {
        return -1;
    }

    if (init_mqtt() < 0) {
        return -1;
    }

    if (publish_mqtt() < 0) {
        return -1;
    }

    while (1) {
        publish_mqtt();
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/v4l2.h>

#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

#define MAX_BUFFER_SIZE 65536

typedef struct {
    int fd;
    struct v4l2_buffer buffer;
    unsigned char buffer_data[MAX_BUFFER_SIZE];
} CameraCapture;

CameraCapture capture;

void init_capture() {
    int err;
    char buffer_name[100];

    // Open the camera device
    snprintf(buffer_name, sizeof(buffer_name), "/dev/video0");
    capture.fd = open(buffer_name, O_RDWR);
    if (capture.fd == -1) {
        perror("Failed to open camera device");
        exit(EXIT_FAILURE);
    }

    // Set the desired image parameters
    struct v4l2_capability cap;
    err = ioctl(capture.fd, VIDIOC_QUERYCAP, &cap);
    if (err < 0) {
        perror("Failed to query camera capabilities");
        exit(EXIT_FAILURE);
    }

    if (!cap.capabilities.cap_videocodec || !cap.capabilities.cap_image) {
        fprintf(stderr, "Camera does not support video capture\n");
        exit(EXIT_FAILURE);
    }

    struct v4l2_format fmt;
    fmt.type = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.sizeimage = fmt.fmt.pix.width * fmt.fmt.pix.height * 2;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;

    err = ioctl(capture.fd, VIDIOC_S_FMT, &fmt);
    if (err < 0) {
        perror("Failed to set image format");
        exit(EXIT_FAILURE);
    }

    // Set the buffer size
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_CIRCULAR;
    buf.index = 0;
    buf.size = fmt.fmt.pix.sizeimage;
    err = ioctl(capture.fd, VIDIOC_S_BUFFER, &buf);
    if (err < 0) {
        perror("Failed to set buffer size");
        exit(EXIT_FAILURE);
    }
}

void capture_image() {
    int err;
    struct v4l2_frame buffer;
    unsigned char *image_data = capture.buffer_data;

    // Capture the image
    err = ioctl(capture.fd, VIDIOC_DQBUF, &buffer);
    if (err < 0) {
        if (buffer.mii < 0) {
            fprintf(stderr, "Failed to dequeue buffer\n");
            exit(EXIT_FAILURE);
        } else {
            fprintf(stderr, "Failed to capture image: %d\n", buffer.mii);
            exit(EXIT_FAILURE);
        }
    }

    // Copy the image data to the buffer_data array
    memcpy(image_data, buffer.image, buffer.bytesperframe);
    // Free the buffer
    free(buffer.image);

    // Save the image to a file
    FILE *file = fopen("image.yuv", "wb");
    if (!file) {
        perror("Failed to open image file");
        exit(EXIT_FAILURE);
    }
    fwrite(image_data, buffer.bytesperframe, 1, file);
    fclose(file);

    // Return the buffer to the camera
    err = ioctl(capture.fd, VIDIOC_QBUF, &buffer);
    if (err < 0) {
        perror("Failed to return buffer to the camera");
        exit(EXIT_FAILURE);
    }
}

int main() {
    init_capture();

    capture_image();

    // Release resources
    close(capture.fd);

    return 0;
}

