int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_from_file(fd, 0)) == NULL) {
        perror("gpiod_chip_from_file");
        gpiod_close(fd);
        return 1;
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 17)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an edge loop
    if ((loop = gpiod_loop_from_line(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_loop_from_line");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(loop, line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high
    if (gpiod_line_set_value(loop, line, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_loop_close(loop);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Print initial state
    printf("Initial state: High\n");

    // Run 3 cycles
    for (int i = 0; i < 3; i++) {
        // Set the line to low
        if (gpiod_line_set_value(loop, line, 0) < 0) {
            perror("gpiod_line_set_value");
            gpiod_loop_close(loop);
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            gpiod_close(fd);
            return 1;
        }

        // Print state
        printf("Cycle %d: Low\n", i + 1);

        // Set the line to high
        if (gpiod_line_set_value(loop, line, 1) < 0) {
            perror("gpiod_line_set_value");
            gpiod_loop_close(loop);
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            gpiod_close(fd);
            return 1;
        }

        // Print state
        printf("Cycle %d: High\n", i + 1);
    }

    // Print final state
    printf("Final state: High\n");

    // Close the loop
    if (gpiod_loop_close(loop) < 0) {
        perror("gpiod_loop_close");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Close the line
    if (gpiod_line_close(line) < 0) {
        perror("gpiod_line_close");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Close the chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
        gpiod_close(fd);
        return 1;
    }

    // Close the GPIO device
    if (gpiod_close(fd) < 0) {
        perror("gpiod_close");
        return 1;
    }

    printf("Program exited normally.\n");
    return 0;
}

