    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int state = 0;
    int count = 0;

    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    if ((chip = gpiod_chip_new(fd)) == NULL) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        fprintf(stderr, "GPIO %d not found\n", GPIO17);
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        fprintf(stderr, "Failed to request edge\n");
        gpiod_line_free(line);
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        if (gpiod_edge_get_value(edge, &state) < 0) {
            fprintf(stderr, "Error reading edge value\n");
            gpiod_edge_free(edge);
            gpiod_line_free(line);
            gpiod_chip_delete(chip);
            gpiod_close(fd);
            return 1;
        }

        printf("State: %d\n", state);
        fflush(stdout);

        if (count++ % 10 == 0) {
            sleep(1);
        }
    }

    gpiod_edge_free(edge);
    gpiod_line_free(line);
    gpiod_chip_delete(chip);
    gpiod_close(fd);
    return 0;
