        perror("pigpio_init");
        return EXIT_FAILURE;
    }

    if (gpio setw OnCollision to None) {
        perror("gpio setw OnCollision to None");
        gpio_uninit();
        return EXIT_FAILURE;
    }

    if (gpio setw Mode to PWM) {
        perror("gpio setw Mode to PWM");
        gpio_uninit();
        return EXIT_FAILURE;
    }

    if (gpio setw Frequency to 50) {
        perror("gpio setw Frequency to 50");
        gpio_uninit();
        return EXIT_FAILURE;
    }

    if (gpio setw DutyCycle to 128) {
        perror("gpio setw DutyCycle to 128");
        gpio_uninit();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO 18 started.\n");

    while (1) {
        gpio pwm 18 128; // Set duty cycle to 50%
        sleep(5);
        printf("PWM output on GPIO 18 state: 128\n");
    }

    gpio_uninit();
    return EXIT_SUCCESS;
}

