#define PCF8574_ADDR 0x20
#define PCF8574_I2C_DEVICE "/dev/i2c-1"

int main() {
    int i2c_fd;
    int result;

    // Open the I2C device
    if ((i2c_fd = open(PCF8574_I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Define the register address for the PCF8574
    unsigned char reg_addr = 0x00;

    // Define the data to be written to the register
    unsigned char data[8] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};

    // Write data to the register
    for (int i = 0; i < 8; i++) {
        if (write(i2c_fd, &data[i], 1) != 1) {
            perror("Failed to write to I2C device");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    // Close the I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
