int main() {
    int fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    int line_fd = gpiod_get_line(fd, 16, GPIOD_LINE_ACTIVE_LOW);
    if (line_fd < 0) {
        perror("gpiod_get_line");
        gpiod_close(fd);
        return 1;
    }

    int direction_fd = gpiod_get_fd(line_fd, GPIODIRECTION_OUTPUT);
    if (direction_fd < 0) {
        perror("gpiod_get_fd");
        gpiod_close(fd);
        gpiod_close(line_fd);
        return 1;
    }

    int value_fd = gpiod_get_value(line_fd, 0);
    if (value_fd < 0) {
        perror("gpiod_get_value");
        gpiod_close(fd);
        gpiod_close(line_fd);
        gpiod_close(direction_fd);
        return 1;
    }

    // Set the output to 1 (high)
    if (gpiod_set_value(line_fd, 1) < 0) {
        perror("gpiod_set_value");
        gpiod_close(fd);
        gpiod_close(line_fd);
        gpiod_close(direction_fd);
        gpiod_close(value_fd);
        return 1;
    }

    printf("Output set to high\n");

    // Wait for 1 second
    sleep(1);

    // Set the output to 0 (low)
    if (gpiod_set_value(line_fd, 0) < 0) {
        perror("gpiod_set_value");
        gpiod_close(fd);
        gpiod_close(line_fd);
        gpiod_close(direction_fd);
        gpiod_close(value_fd);
        return 1;
    }

    printf("Output set to low\n");

    // Release resources
    gpiod_close(fd);
    gpiod_close(line_fd);
    gpiod_close(direction_fd);
    gpiod_close(value_fd);

    return 0;
}

