int main() {
    int error = 0;

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        error = 1;
    }

    if (error == 0) {
        printf("PWM initialized\n");
        for (;;) {
            // Set PWM on GPIO 18 to 50% duty cycle
            gpioServo(18, 500000); // 50% duty cycle (500000 microseconds)
            usleep(100000); // Wait 0.1 seconds

            // Set PWM on GPIO 23 to 50% duty cycle
            gpioServo(23, 500000);

            // Set PWM on GPIO 24 to 50% duty cycle
            gpioServo(24, 500000);

            // Wait 0.1 seconds
            usleep(100000);
        }
    }

    if (error == 0) {
        gpioTerminate();
    }

    return error;
}

