        gpiod_close(fd);
        return 1;
    }

    // Create an edge to detect changes
    edge = gpiod_loop_add_edge(loop, line, GPIOD_EDGE_BOTH);
    if (!edge) {
        perror("gpiod_loop_add_edge");
        gpiod_loop_destroy(loop);
        gpiod_close(fd);
        return 1;
