        perror("gpiod_loop_stop");
        gpiod_loop_destroy(loop);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Free resources
    gpiod_loop_destroy(loop);
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

