#define SHT31_ADDR 0x44
#define SHT31_REG_TEMP_HOLD 0x00
#define SHT31_REG_TEMP_MSB 0x01
#define SHT31_REG_TEMP_LSB 0x02
#define SHT31_REG_HUM_HOLD 0x04
#define SHT31_REG_HUM_MSB 0x05
#define SHT31_REG_HUM_LSB 0x06

#define SHT31_ERROR_NONE 0
#define SHT31_ERROR_NO_DEVICE -1
#define SHT31_ERROR_INVALID -2
#define SHT31_ERROR_INVALID_DATA -3

int sht31_fd = -1;

void sht31_init() {
    if ((sht31_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sht31_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }
}

void sht31_read_data(int *temp_hum) {
    char buf[9];
    int ret;

    buf[0] = SHT31_REG_TEMP_HOLD;
    ret = ioctl(sht31_fd, I2C_RDWR, buf);
    if (ret < 0) {
        perror("Failed to read temperature data");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_TEMP_MSB;
    ret = read(sht31_fd, buf + 1, 2);
    if (ret < 0) {
        perror("Failed to read temperature MSB");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_TEMP_LSB;
    ret = read(sht31_fd, buf + 3, 2);
    if (ret < 0) {
        perror("Failed to read temperature LSB");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_HUM_HOLD;
    ret = ioctl(sht31_fd, I2C_RDWR, buf);
    if (ret < 0) {
        perror("Failed to read humidity data");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_HUM_MSB;
    ret = read(sht31_fd, buf + 1, 2);
    if (ret < 0) {
        perror("Failed to read humidity MSB");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_HUM_LSB;
    ret = read(sht31_fd, buf + 3, 2);
    if (ret < 0) {
        perror("Failed to read humidity LSB");
        exit(EXIT_FAILURE);
    }

    *temp_hum = (buf[1] << 8) | buf[0];
    *temp_hum |= (buf[3] << 8) | buf[2];
    *temp_hum &= 0xFFFC;

    buf[0] = SHT31_REG_HUM_MSB;
    ret = read(sht31_fd, buf + 1, 2);
    if (ret < 0) {
        perror("Failed to read humidity MSB");
        exit(EXIT_FAILURE);
    }

    buf[0] = SHT31_REG_HUM_LSB;
    ret = read(sht31_fd, buf + 3, 2);
    if (ret < 0) {
        perror("Failed to read humidity LSB");
        exit(EXIT_FAILURE);
    }

    *temp_hum = (buf[1] << 8) | buf[0];
    *temp_hum |= (buf[3] << 8) | buf[2];
    *temp_hum &= 0xFFFC;

    return;
}

int main() {
    sht31_init();

    while (1) {
        int temp_hum = 0;
        sht31_read_data(&temp_hum);

        if (temp_hum == SHT31_ERROR_NO_DEVICE) {
            printf("Error: SHT31 device not found\n");
            exit(EXIT_FAILURE);
        }

        if (temp_hum == SHT31_ERROR_INVALID) {
            printf("Error: Invalid data from SHT31\n");
            exit(EXIT_FAILURE);
        }

        double temp = (temp_hum * 0.01) / 16384.0;
        double humidity = (temp_hum * 0.01) / 16384.0;

        printf("%.1f %f\n", temp, humidity);

        sleep(5);
    }

    close(sht31_fd);
    return 0;
}

