    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Print the initial state
    printf("GPIO 18 (BCM) set to HIGH\n");

    // Loop indefinitely, printing the state every 5 seconds
    while (1) {
        // Print the state
        printf("GPIO 18 (BCM) state: %d\n", gpiod_line_get_value(line));
        fflush(stdout);

        // Sleep for 5 seconds
        if (sleep(5) < 0) {
            perror("sleep");
            goto cleanup;
        }
    }

cleanup:
    // Release the edge
    if (edge) {
        gpiod_edge_free(edge);
    }

    // Release the line
    if (line) {
        gpiod_line_release(line);
    }

    // Release the chip
    if (chip) {
        gpiod_chip_release(chip);
    }

    // Close the GPIO device
    if (fd >= 0) {
        gpiod_close(fd);
    }

    return EXIT_SUCCESS;
}

