    }
    line = gpiod_chip_get_line(chip, GPIOD_LINE_18);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create a loop for the lines
    loop = gpiod_loop_new(chip, 2);
    if (loop == NULL) {
        perror("gpiod_loop_new");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the direction of the lines to output
    err = gpiod_loop_set_direction(loop, line, GPIOD_DIR_OUT);
    if (err < 0) {
        perror("gpiod_loop_set_direction");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }
    err = gpiod_loop_set_direction(loop, line + 1, GPIOD_DIR_OUT);
    if (err < 0) {
        perror("gpiod_loop_set_direction");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Set the lines to output 1 (high)
    err = gpiod_loop_set_value(loop, line, 1);
    if (err < 0) {
        perror("gpiod_loop_set_value");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }
    err = gpiod_loop_set_value(loop, line + 1, 1);
    if (err < 0) {
        perror("gpiod_loop_set_value");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Create a loop for edge detection
    edge = gpiod_line_get_edge(chip, line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("gpiod_line_get_edge");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Create a loop for the edge
    loop = gpiod_edge_get_loop(chip, edge, GPIOD_EDGE_LOOP);
    if (loop == NULL) {
        perror("gpiod_edge_get_loop");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        gpiod_line_put_edge(chip, line, NULL);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Start the loop
    err = gpiod_loop_start(loop);
    if (err < 0) {
        perror("gpiod_loop_start");
        gpiod_chip_close(chip);
        gpiod_loop_close(loop);
        gpiod_line_put_edge(chip, line, NULL);
        gpiod_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Print the state
        printf("GPIO 17: %d, GPIO 18: %d\n", gpiod_loop_get_value(loop, line), gpiod_loop_get_value(loop, line + 1));
        fflush(stdout);

        // Sleep for 1 second
        err = gpiod_loop_wait(loop, 1);
        if (err < 0) {
            perror("gpiod_loop_wait");
            gpiod_chip_close(chip);
            gpiod_loop_close(loop);
            gpiod_line_put_edge(chip, line, NULL);
            gpiod_loop_close(loop);
            exit(EXIT_FAILURE);
        }
    }

    // Exit cleanly
    gpiod_chip_close(chip);
    gpiod_loop_close(loop);
    gpiod_line_put_edge(chip, line, NULL);
    gpiod_loop_close(loop);
    return 0;
}

