    if ((loop = gpiod_loop_from_line(line)) == NULL) {
        perror("gpiod_loop_from_line");
        return 1;
    }

    // Create an edge for the loop
    if ((edge = gpiod_loop_get_edge(loop, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_loop_get_edge");
        return 1;
    }

    // Set the edge to trigger on both rising and falling edges
    if (gpiod_edge_set_mode(edge, GPIOD_MODE_EDGE_BOTH) < 0) {
        perror("gpiod_edge_set_mode");
        return 1;
    }

    // Set the edge to trigger on both rising and falling edges
    if (gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_edge_set_edge");
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_pull(line, GPIOD_PULL_UP) < 0) {
        perror("gpiod_line_set_pull");
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_type(line, GPIOD_TYPE_OUTPUT) < 0) {
        perror("gpiod_line_set_type");
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_value(line, 0) < 0) {
