        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    ret = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH, &edge);
    if (ret < 0) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
