    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int value;
    int i, j;
    int count = 0;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the GPIO chip
    if ((chip = gpiod_chip_from_fd(fd)) == NULL) {
        perror("gpiod_chip_from_fd");
        return 1;
    }

    // Find the GPIO line
    if ((line = gpiod_chip_get_line(chip, DHT22_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        return 1;
    }

    // Set the edge to be triggered on both rising and falling edges
    if (gpiod_edge_set_trigger(edge, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_edge_set_trigger");
        return 1;
    }

    // Start the edge
    if (gpiod_edge_start(edge) < 0) {
        perror("gpiod_edge_start");
        return 1;
    }

    while (count < DHT22_READS) {
        // Wait for an edge
        if (gpiod_edge_wait(edge, &value) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                perror("gpiod_edge_wait");
                return 1;
            }
        }

        // Check if the value is valid
        if (value == 0) {
            // Read the DHT22
            if ((value = gpiod_line_read(line)) < 0) {
                perror("gpiod_line_read");
                return 1;
            }

            // Check if the reading is valid
