                // Read the temperature and humidity
                if ((value = gpiod_line_read(line)) < 0) {
                    perror("gpiod_line_read");
                    return 1;
                }
                if ((value = gpiod_line_read(line)) < 0) {
                    perror("gpiod_line_read");
                    return 1;
                }

                // Check if the reading is valid
                if (value == 0) {
                    // Print the state
                    printf("Temperature: %.1f°C, Humidity: %.1f%%\n", value, value);
                    count++;
                } else {
                    printf("Invalid reading\n");
                }
            } else {
                printf("Invalid reading\n");
            }
        } else {
            printf("Invalid reading\n");
        }
    }

    // Stop the edge
    if (gpiod_edge_stop(edge) < 0) {
        perror("gpiod_edge_stop");
        return 1;
    }

    // Release the line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
        return 1;
    }

    // Release the chip
    if (gpiod_chip_release(chip) < 0) {
        perror("gpiod_chip_release");
        return 1;
    }

    // Close the GPIO device
    if (gpiod_close(fd) < 0) {
        perror("gpiod_close");
        return 1;
    }

    return 0;
}

