    int pwm27 = gpio_pwm_create(gpiod, gpio27, 1);
    if (pwm17 < 0 || pwm27 < 0) {
        perror("gpio_pwm_create");
        gpiod_uninit();
        return 1;
    }

    int pwm17_state = 0;
    int pwm27_state = 0;

    while (1) {
        printf("PWM17: %d, PWM27: %d\n", pwm17_state, pwm27_state);
