    if (ret < 0) {
        perror("gpiod_edge_request_event");
        goto cleanup;
    }

    // Set the event to trigger on both rising and falling edges
    ret = gpiod_event_set_trigger(event, GPIOD_EDGE_BOTH);
    if (ret < 0) {
        perror("gpiod_event_set_trigger");
        goto cleanup;
    }

    // Start the event
    ret = gpiod_event_start(event);
    if (ret < 0) {
        perror("gpiod_event_start");
        goto cleanup;
    }

