    }

    chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_list_lines(chip, &line, NULL) < 1) {
        perror("gpiod_chip_list_lines");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_name(chip, line, NULL) < 0) {
        perror("gpiod_chip_get_line_name");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (gpiod_chip_get_line_number(chip, line, &line_number) < 0) {
        perror("gpiod_chip_get_line_number");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    if (line_number != 8) {
        fprintf(stderr, "Expected GPIO 8, got %d\n", line_number);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, line_number);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    loop = gpiod_loop_new(chip, line, GPIOD_EDGE_BOTH);
    if (!loop) {
        fprintf(stderr, "Failed to create loop\n");
        gpiod_loop_destroy(loop);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 2; j++) {
            if (gpiod_loop_poll(loop, 0) < 0) {
                perror("gpiod_loop_poll");
                gpiod_loop_destroy(loop);
                gpiod_chip_free(chip);
                gpiod_close(fd);
                return 1;
            }
            if (j == 0) {
                gpiod_line_set_value(line, 1);
                printf("GPIO 8: HIGH\n");
            } else {
                gpiod_line_set_value(line, 0);
                printf("GPIO 8: LOW\n");
            }
            sleep(1);
        }
    }

    gpiod_loop_destroy(loop);
    gpiod_chip_free(chip);
    gpiod_close(fd);
    return 0;
}

