    exit(EXIT_SUCCESS);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    struct sigaction sa;

    sa.sa_handler = handle_spi_error;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_transfer.speed = SPI_SPEED;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.mode = SPI_MODE;
    spi_transfer.len = 3;
    spi_transfer.cs = SPI_CS;

    while (1) {
        ssize_t bytes_read = 0;
        uint16_t c1, c2, c3;

        spi_transfer.tx_buf = (unsigned char *) &spi_transfer;
        spi_transfer.rx_buf = (unsigned char *) &c1;
        spi_transfer.delay_usecs = 0;
        bytes_read = write(spi_fd, &spi_transfer, sizeof(spi_transfer));
