int main() {
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    chip = gpiod_chip_open(GPIOD_DEVICE_NAME);
    if (chip == NULL) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Find the GPIO line
    line = gpiod_chip_get_line(chip, 18);
    if (line == NULL) {
        perror("GPIO line 18 not found");
        gpiod_chip_close(chip);
        return 1;
    }

    // Create a loop for the line
    loop = gpiod_line_request_loop(line, GPIOD_EDGE_BOTH);
    if (loop == NULL) {
        perror("Failed to create loop");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Create an edge for the loop
    edge = gpiod_loop_request_edge(loop, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to create edge");
        gpiod_loop_free(loop);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the output mode
    if (gpiod_edge_set_mode(edge, GPIOD_MODE_OUTPUT) != 0) {
        perror("Failed to set output mode");
        gpiod_edge_free(edge);
        gpiod_loop_free(loop);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the value to 1 (on)
    if (gpiod_edge_set_value(edge, 1) != 0) {
        perror("Failed to set value");
        gpiod_edge_free(edge);
        gpiod_loop_free(loop);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

