#define BMP280_ADDR 0x03
#define BMP280_REG_TEMP_MSB 0xF6
#define BMP280_REG_TEMP_LSB 0xF7
#define BMP280_REG_PRESS_MSB 0xF3
#define BMP280_REG_PRESS_LSB 0xF4
#define BMP280_REG_PRESS_X1 0xF5
#define BMP280_REG_PRESS_X2 0xF6
#define BMP280_REG_PRESS_X3 0xF7
#define BMP280_REG_PRESS_X4 0xF8
#define BMP280_REG_PRESS_X5 0xF9
#define BMP280_REG_PRESS_OS_TEMP 0xFA
#define BMP280_REG_PRESS_OS_P 0xFB
#define BMP280_REG_CONFIG 0xF2

int bmp280_fd = -1;

void i2c_open(const char *dev) {
    bmp280_fd = open(dev, O_RDWR);
    if (bmp280_fd == -1) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    if (bmp280_fd != -1) {
        close(bmp280_fd);
    }
}

void i2c_read_register(int reg) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    msg[0].addr = BMP280_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = reg;
    req.msg = msg;
    req.len = 1;

    if (ioctl(bmp280_fd, I2C_RDWR, &req) == -1) {
        perror("Failed to read from i2c device");
        i2c_close();
        exit(EXIT_FAILURE);
    }

    int value = msg[0].data[0];
    printf("%d\n", value);
}

