    i2c_open("/dev/i2c-1");

    for (int i = 0; i < 3; i++) {
        i2c_read_register(BMP280_REG_TEMP_MSB);
        i2c_read_register(BMP280_REG_TEMP_LSB);
        i2c_read_register(BMP280_REG_PRESS_MSB);
        i2c_read_register(BMP280_REG_PRESS_LSB);
        i2c_read_register(BMP280_REG_PRESS_X1);
        i2c_read_register(BMP280_REG_PRESS_X2);
        i2c_read_register(BMP280_REG_PRESS_X3);
        i2c_read_register(BMP280_REG_PRESS_X4);
        i2c_read_register(BMP280_REG_PRESS_X5);
        i2c_read_register(BMP280_REG_PRESS_OS_TEMP);
        i2c_read_register(BMP280_REG_PRESS_OS_P);
        i2c_read_register(BMP280_REG_CONFIG);
    }

    i2c_close();
    return 0;
}

