    err = gpiod_direction_set(line, GPIOD_DIR_OUT);
    if (err < 0) {
        perror("gpiod_direction_set");
        goto cleanup;
    }

    // Set the value to 0 (off)
    err = gpiod_set_value(line, 0);
    if (err < 0) {
        perror("gpiod_set_value");
        goto cleanup;
    }

    printf("Output on GPIO 18 (BCM) set to 0 (off)\n");

    // Loop indefinitely to keep the output active
    while (1) {
        // Simulate a read operation with a validity check
        struct gpiod_value val;
