int main() {
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int value;

    err = gpiod_open("/dev/gpiod");
    if (err < 0) {
        perror("gpiod_open");
        return 1;
    }

    chip = gpiod_get_chip(err);
    if (!chip) {
        perror("gpiod_get_chip");
        gpiod_close(err);
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_close(err);
        return 1;
    }

    err = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (err < 0) {
        perror("gpiod_line_request_edge");
        gpiod_close(err);
        return 1;
    }

    edge = gpiod_line_get_edge(line, err);
    if (!edge) {
        perror("gpiod_line_get_edge");
        gpiod_close(err);
        return 1;
    }

    while (1) {
        err = gpiod_edge_get_value(edge, &value);
        if (err < 0) {
            perror("gpiod_edge_get_value");
            gpiod_line_put_edge(line, err);
            gpiod_close(err);
            return 1;
        }

        printf("GPIO 17: %d\n", value);
        usleep(100000); // 0.1 seconds
    }

    gpiod_line_put_edge(line, err);
    gpiod_chip_put(chip, err);
    gpiod_close(err);

    return 0;
}

