#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x76
#define BME280_REG_MEASUREMENT 0xF2

int main() {
    int fd;
    struct i2c_msg msg[3];
    struct i2c_rdwr_msg wrq;
    int i, result;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        close(fd);
        return 1;
    }

    for (i = 0; i < 3; i++) {
        memset(&msg[i], 0, sizeof(struct i2c_msg));
        msg[i].msg._ifc = I2C_RDWR;
        msg[i].msg.i2c_rdwr = wrq;
        msg[i].addr = I2C_ADDR;
        msg[i].flags = 0;
        msg[i].data[0] = BME280_REG_MEASUREMENT;
        msg[i].len = 1;

        result = ioctl(fd, I2C_SMBUS_READ, msg[i]);
        if (result < 0) {
            perror("Failed to read from BME280");
            close(fd);
            return 1;
        }

        // Print the measurement
        printf("Temperature: %.2f°C, Humidity: %.2f%, Pressure: %.2f hPa\n",
               (float)msg[i].data[0] / 256.0,
               (float)msg[i].data[1] / 256.0,
               (float)(msg[i].data[2] + (msg[i].data[3] << 8)) / 100.0);
        usleep(5000000); // 5 seconds
    }

    close(fd);
    return 0;
}

