#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO18 18

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int count = 0;
    int distance = 0;
    int timeout = 500000; // 0.5 seconds in microseconds

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_close(fd);
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Create an event for the edge
    if ((event = gpiod_edge_request_event(edge, GPIOD_EDGE_BOTH, 0)) == NULL) {
        perror("gpiod_edge_request_event");
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Start the event
    if (gpiod_event_start(event) < 0) {
        perror("gpiod_event_start");
        gpiod_event_free(event);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    while (1) {
        // Read the event
        if (gpiod_event_read(event, &distance) < 0) {
            perror("gpiod_event_read");
            gpiod_event_free(event);
            gpiod_edge_free(edge);
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            gpiod_close(fd);
            return 1;
        }

        // Check if the reading is valid
        if (distance > 0 && distance < 2000) {
            printf("Distance: %d cm\n", distance);
        } else {
            printf("Invalid reading\n");
        }

        // Sleep for 0.5 seconds
        usleep(timeout);
    }

    // Clean up resources
    gpiod_event_free(event);
    gpiod_edge_free(edge);
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

