int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        goto cleanup;
    }

    // Get the first line
    if ((line = gpiod_chip_get_line(chip, 8)) == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create an edge
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Create a loop
    if ((loop = gpiod_edge_create_loop(edge, GPIOD_LOOP_NOWAIT)) == NULL) {
        perror("gpiod_edge_create_loop");
        goto cleanup;
    }

    // Set the direction to output
    if (gpiod_line_set_direction(line, GPIOD_DIR_OUT)) {
        printf("Direction set to output\n");
    } else {
        perror("gpiod_line_set_direction");
        goto cleanup;
    }

    // Start the loop
    if (gpiod_loop_start(loop)) {
        printf("Loop started\n");
    } else {
        perror("gpiod_loop_start");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Sleep for 0.001 seconds
        if (sleep(0.001) == -1) {
            perror("sleep");
            goto cleanup;
        }

        // Print the state
        printf("State: %s\n", gpiod_line_get_value(line) ? "High" : "Low");
    }

cleanup:
    // Release the hardware
    if (gpiod_loop_destroy(loop)) {
        perror("gpiod_loop_destroy");
    }
    if (gpiod_edge_free(edge)) {
        perror("gpiod_edge_free");
    }
    if (gpiod_line_free(line)) {
        perror("gpiod_line_free");
    }
    if (gpiod_chip_free(chip)) {
        perror("gpiod_chip_free");
    }
    if (gpiod_close(fd)) {
        perror("gpiod_close");
    }

    return EXIT_SUCCESS;
}

