#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_XYZ 0x00

int main() {
    int file;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    uint8_t data[6];

    file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set slave address");
        close(file);
        return 1;
    }

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 6;

    for (int i = 0; i < 6; i++) {
        data[i] = 0;
    }

    rdwr_msg.msgs = msg;
    rdwr_msg.nummsgs = 1;

    if (ioctl(file, I2C_RDWR, &rdwr_msg) < 0) {
        perror("Failed to read from i2c device");
        close(file);
        return 1;
    }

    for (int i = 0; i < 6; i += 2) {
        data[i] = msg[0].data[i];
        data[i + 1] = msg[0].data[i + 1];
    }

    for (int i = 0; i < 3; i++) {
        printf("%f ", (float) data[i * 2] / 256.0);
    }
    printf("\n");

    close(file);
    return 0;
}

