            gpiod_loop_free(loop);
            gpiod_edge_free(edge);
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Print current state
        printf("State: %d\n", gpiod_line_get_value(line));
    }

    // Exit cleanly
    gpiod_loop_free(loop);
    gpiod_edge_free(edge);
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    return 0;
}

