int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Get the first chip
    if ((chip = gpiod_chip_from_fd(fd)) == NULL) {
        perror("gpiod_chip_from_fd");
        goto cleanup;
    }

    // Find the GPIO line with number 4 (BCM)
    if ((line = gpiod_chip_get_line(chip, 4)) == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create a loop for the line
    if ((loop = gpiod_loop_from_line(line)) == NULL) {
        perror("gpiod_loop_from_line");
        goto cleanup;
    }

    // Create an edge for the line
    if ((edge = gpiod_edge_create(loop)) == NULL) {
        perror("gpiod_edge_create");
        goto cleanup;
    }

    // Set the edge to edge_detect
    if (gpiod_edge_set_mode(edge, GPIOD_EDGE_DETECT) < 0) {
        perror("gpiod_edge_set_mode");
        goto cleanup;
    }

    // Set the edge to trigger on a rising edge
    if (gpiod_edge_set_trigger(edge, GPIOD_EDGE_RISING) < 0) {
        perror("gpiod_edge_set_trigger");
        goto cleanup;
    }

    // Add the edge to the loop
    if (gpiod_loop_add_edge(loop, edge) < 0) {
        perror("gpiod_loop_add_edge");
        goto cleanup;
    }

    // Start the loop
    if (gpiod_loop_start(loop) < 0) {
        perror("gpiod_loop_start");
        goto cleanup;
    }

    // Print the initial state
    printf("Initial state: %s\n", gpiod_line_get_value(line) ? "HIGH" : "LOW");

    // Main loop
    while (1) {
        // Wait for 0.5 seconds
        if (sleep(0.5) < 0) {
            perror("sleep");
            goto cleanup;
        }

        // Toggle the line
        if (gpiod_line_set_value(line, 1 - gpiod_line_get_value(line)) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        // Print the new state
        printf("State toggled: %s\n", gpiod_line_get_value(line) ? "HIGH" : "LOW");
    }

cleanup:
    // Release the hardware
    if (gpiod_loop_destroy(loop) < 0) {
        perror("gpiod_loop_destroy");
    }
    if (gpiod_edge_destroy(edge) < 0) {
        perror("gpiod_edge_destroy");
    }
    if (gpiod_chip_free(chip) < 0) {
        perror("gpiod_chip_free");
    }
    if (gpiod_close(fd) < 0) {
        perror("gpiod_close");
    }

    return EXIT_SUCCESS;
}

