        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the direction to input
    if ((direction = gpiod_line_direction(line, GPIOD_DIR_IN)) < 0) {
        perror("gpiod_line_direction");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the edge to rising
    if ((edge = gpiod_line_edge(line, GPIOD_EDGE_RISING)) == NULL) {
        perror("gpiod_line_edge");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Register the edge
    if ((gpiod_edge_register(edge)) < 0) {
        perror("gpiod_edge_register");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    // Loop to detect rising edge
    while (1) {
        // Read the value
        if ((value = gpiod_line_value(line)) < 0) {
            perror("gpiod_line_value");
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            gpiod_close(fd);
            return 1;
        }

        // Print the value
        printf("Value: %d\n", value);

        // Wait for the next edge
        usleep(100000); // 100ms
    }

    // Release resources
    gpiod_edge_unregister(edge);
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    gpiod_close(fd);

    return 0;
}

