#define I2C_DEVICE "/dev/i2c-" I2C_BUS

int i2c_fd;

void i2c_open() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    close(i2c_fd);
}

void i2c_read(uint8_t reg, uint8_t *buf, size_t size) {
    if (ioctl(i2c_fd, I2C_SMBUS_READ, reg, buf, size) < 0) {
        perror("Failed to read from i2c device");
        i2c_close();
        exit(EXIT_FAILURE);
    }
}

void i2c_write(uint8_t reg, uint8_t *buf, size_t size) {
