        perror("Failed to write to i2c device");
        i2c_close();
        exit(EXIT_FAILURE);
    }
}

int main() {
    i2c_open();

    uint8_t id[1], red[1], green[1], blue[1], white[1];

    while (1) {
        i2c_read(TCS34725_REG_ID, id, 1);
        if (id[0] != 0x60) {
            printf("TCS34725 device not found\n");
            i2c_close();
            exit(EXIT_FAILURE);
        }

        i2c_read(TCS34725_REG_RED, red, 1);
        i2c_read(TCS34725_REG_GREEN, green, 1);
        i2c_read(TCS34725_REG_BLUE, blue, 1);
        i2c_read(TCS34725_REG_WHITE, white, 1);

        printf("R: %d, G: %d, B: %d, W: %d\n", red[0], green[0], blue[0], white[0]);

        usleep(500000); // 0.5 seconds

        // Clean up on exit
        i2c_close();
    }

    return 0;
}

