    int state;

    // Open the GPIO device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        gpiod_close(fd);
        return 1;
    }

    // Get the GPIO line
    if ((line = gpiod_chip_get_line(chip, 18)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to high (1)
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set up an edge detection
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Start the edge detection
    if (gpiod_edge_start(edge) < 0) {
        perror("gpiod_edge_start");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        gpiod_close(fd);
        return 1;
    }

    // Read the state
    while (1) {
        if ((state = gpiod_edge_get_value(edge)) == 0) {
            printf("High\n");
        } else {
            printf("Low\n");
        }
        usleep(100000); // 0.1 seconds
    }

    // Cleanup
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    gpiod_close(fd);

    return 0;
}

