#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_XG_A 0x43

int main() {
    int file;
    char *dev = "/dev/i2c-1";
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    uint8_t data[8];

    file = open(dev, O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set slave address");
        close(file);
        return 1;
    }

    while (1) {
        msg[0].addr = MPU6050_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].len = 1;
        msg[0].data[0] = MPU6050_REG_XG_A;

        msg[1].addr = MPU6050_ADDR;
        msg[1].flags = I2C_M_RD;
        msg[1].len = 1;
        msg[1].data[0] = MPU6050_REG_YG_A;

        if (ioctl(file, I2C_RDWR, msg, &rdwr_msg) < 0) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (rdwr_msg.msgs[0].err != 0) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (rdwr_msg.msgs[1].err != 0) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        data[0] = rdwr_msg.msgs[0].data[0];
        data[1] = rdwr_msg.msgs[1].data[0];

        printf("%d %d\n", data[0], data[1]);

        usleep(1000000); // 1 second delay
    }

    close(file);
    return 0;
}

